using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public class IncomingMissionTests
{
    static WorldSession Sent(bool optional=false,int due=60){var s=new WorldSession(IncomingMission.Create());Assert.Equal(ResultCode.Accepted,s.Submit(IncomingMission.Build(s.DiagnosticSnapshot(),"request:incoming",optional,due),s.Revision).Code);return s;}
    static void Open(WorldSession s){s.AdvanceTo(1);var c=Assert.Single(IncomingMission.View(s,ContractFixture.Officer));Assert.True(c.CanOpen);Assert.Equal(ResultCode.Accepted,s.Open(ContractFixture.Officer,c.Message,s.Revision).Code);}
    [Fact] public void UnopenedDoesNotExposeContents(){var s=Sent();Assert.Empty(IncomingMission.View(s,ContractFixture.Officer));s.AdvanceTo(1);Assert.True(s.Paused);var c=Assert.Single(IncomingMission.View(s,ContractFixture.Officer));Assert.Null(c.Task);Assert.DoesNotContain("点検",c.Text);Assert.False(c.CanDecide);Assert.Empty(s.GetActorView(ContractFixture.Officer).Tasks);}
    [Fact] public void BindingOrderIsNotOptional(){var s=Sent();Open(s);var c=Assert.Single(IncomingMission.View(s,ContractFixture.Officer));Assert.False(c.CanDecide);Assert.Equal(ExecutionPhase.Running,s.DiagnosticSnapshot().Tasks.Single().Execution);Assert.Equal(ResultCode.NotAvailable,s.Assent(c.Task!.Value,ContractFixture.Officer,false,s.Revision).Code);}
    [Theory][InlineData(true)][InlineData(false)] public void AssentGatesWorkAndDuplicate(bool accept){var s=Sent(true);Open(s);var c=Assert.Single(IncomingMission.View(s,ContractFixture.Officer));Assert.True(c.CanDecide);Assert.Empty(s.DiagnosticSnapshot().Actions);Assert.Equal(ResultCode.Accepted,s.Assent(c.Task!.Value,ContractFixture.Officer,accept,s.Revision).Code);var hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.Assent(c.Task.Value,ContractFixture.Officer,!accept,s.Revision).Code);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));s.SetPaused(false);s.AdvanceTo(12);Assert.Equal(accept?ExecutionPhase.Completed:ExecutionPhase.Stopped,s.DiagnosticSnapshot().Tasks.Single().Execution);Assert.Equal(accept?1:0,s.DiagnosticSnapshot().Actions.Length);Assert.Contains(accept?"受諾":"辞退",IncomingMission.View(s,ContractFixture.Officer).Single().Text);}
    [Fact] public void WaitingExpires(){var s=Sent(true,2);Open(s);s.SetPaused(false);s.AdvanceTo(3);Assert.False(IncomingMission.View(s,ContractFixture.Officer).Single().CanDecide);Assert.Contains("期限を超過",IncomingMission.View(s,ContractFixture.Officer).Single().Text);Assert.Empty(s.DiagnosticSnapshot().Actions);}
    [Fact] public void ExpiryDoesNotOpenLetter(){var s=Sent(false,2);s.AdvanceTo(1);s.SetPaused(false);s.AdvanceTo(12);Assert.Null(IncomingMission.View(s,ContractFixture.Officer).Single().Task);}
    [Fact] public void WrongActorAndStaleRevisionCannotDecide(){var s=Sent(true);Open(s);var id=s.DiagnosticSnapshot().Tasks.Single().Id;Assert.Equal(ResultCode.NotAvailable,s.Assent(id,ContractFixture.Clerk,true,s.Revision).Code);Assert.Equal(ResultCode.StateChanged,s.Assent(id,ContractFixture.Officer,true,s.Revision-1).Code);Assert.Empty(s.DiagnosticSnapshot().Actions);}
    [Fact] public void RetryDoesNotDuplicate(){var s=Sent();var i=s.DiagnosticSnapshot().Requests.Single().Intent;Assert.Equal(ResultCode.AlreadyAccepted,s.Submit(i,s.Revision).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.Submit(i with{Kind=TaskKind.VoluntaryRequest},s.Revision).Code);Assert.Single(s.DiagnosticSnapshot().Tasks);Open(s);s.SetPaused(false);s.AdvanceTo(12);Assert.Single(s.DiagnosticSnapshot().Actions);Assert.Empty(s.DiagnosticSnapshot().Transfers);}
    [Theory][InlineData(true)][InlineData(false)] public void MissingAuthorityOrBondRejects(bool bond){var w=IncomingMission.Create();if(bond)w.ServiceBonds=[];else w.Grants=w.Grants.Where(g=>g.Agent!=ContractFixture.Lord).ToArray();var s=new WorldSession(w);Assert.Equal(bond?ResultCode.InvalidInput:ResultCode.NotAvailable,s.Submit(IncomingMission.Build(w,"request:bad",false),s.Revision).Code);Assert.Empty(s.DiagnosticSnapshot().Tasks);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)] public void SaveResumeMatches(int stage){var s=Sent(true);if(stage>=1)s.AdvanceTo(1);if(stage>=2)Open(s);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"incoming-"+Guid.NewGuid().ToString("N")),w.Definitions);store.Save(s,"stage",w.WorldId,new(0,10));var h=new WorldSessionHost(new(IncomingMission.Create()));Assert.Equal(ResultCode.Accepted,h.CommitLoad(store.Prepare("stage"),h.Current,h.Current.Revision));Assert.Equal(ContractJson.Write(IncomingMission.View(s,ContractFixture.Officer)),ContractJson.Write(IncomingMission.View(h.Current,ContractFixture.Officer)));foreach(var x in new[]{s,h.Current}){x.SetPaused(false);if(stage==0)x.AdvanceTo(1);if(stage<2)x.Open(ContractFixture.Officer,IncomingMission.View(x,ContractFixture.Officer).Single().Message,x.Revision);x.Assent(x.DiagnosticSnapshot().Tasks.Single().Id,ContractFixture.Officer,true,x.Revision);x.SetPaused(false);x.AdvanceTo(12);}Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Actions),ContractJson.Write(h.Current.DiagnosticSnapshot().Actions));Assert.Equal(ContractJson.Write(IncomingMission.View(s,ContractFixture.Officer)),ContractJson.Write(IncomingMission.View(h.Current,ContractFixture.Officer)));}
    [Theory][InlineData(0)][InlineData(3601)] public void InvalidDeadlineRejected(int due){Assert.Throws<InvalidDataException>(()=>IncomingMission.Build(IncomingMission.Create(),"request:bad",false,due));}
    [Fact] public void OldProfileRemainsSeparate(){Assert.False(IncomingMission.Enabled(MissionEntry.Create()));Assert.NotEqual(MissionEntry.Create().Definitions.Version,IncomingMission.Create().Definitions.Version);}
}
